insert into WMS_DB_SCHEMA values ('locmst','loccod','Location Capacity Code','S','1','1','0','0','Specifies if locations are tracked at a unit quantity (Q), volume(V), length (L), case dimension(C) or pallet footprint(P) level.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','locsts','Location Status','S','1','0','0','0','Current disposition of the location.  One of:  Full (F), Partial (P), Empty (E) or Inventory Error (I).','Warehouse Layout');
