insert into WMS_DB_SCHEMA values ('locmst','trvseq','Travel Sequence','S','20','1','0','0','The relative distance between locations, the travel sequence is during work management to find the closest location to an idle user.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','sto_seq','Storage Sequence','S','20','1','0','0','Storage Sequence is used to influence how locations are ordered when they are considered for inbound inventory during Putaway.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','rescod','Shipping Resource Code','S','200','1','0','0','Used to path inventory through processing locations.  The resource code is a mechanism by which that location is reserved for product matching the rescod.  For example, in a shipment staging lane, the rescod is often set to the carcod.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','bay','Bay','S','30','1','0','0','The bay the location belongs to.','Warehouse Layout');
