insert into WMS_DB_SCHEMA values ('locmst','locpos','Location Position','S','30','1','0','0','The position of the location respective to it"s level.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','lochgt','Location Height','F','8','1','0','0','This represents the hgt (in the same units as used on the ftpmst table) of product that the loc will tolerate.  This is evaluated on a per storage request.  For example, in a pallet racking example, the lochgt may be set to 90 (inches).','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','loclen','Location Length','F','8','1','0','0','This field is currently NOT used for storage selection or volume calculation purposes and is only used during 3PL Billing operations.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','locwid','Location Width','F','8','1','0','0','This field is currently NOT used for storage selection or volume calculation purposes and is only used during 3PL Billing operations.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','dck_acc_cod','Dock access code','S','30','1','0','0','Dock access code.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','locvrc','Verification Code','S','20','1','0','0','A "checksum" or alternate identifier which may be used to identify the location.  This is often used in facilities where locations may not be able to be labeled and it is desired to provide an alternate, easy to type, name for the loc.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','maxqvl','Maximum Capacity','F','8','0','0','0','The loccod will indicate what this number actually means (in terms of volume, pallets, etc...).  This represents the maximum storage capacity of the location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','curqvl','Used Capacity','F','8','0','0','0','Much the same as maxqvl, this field is used to indicate the currently used capacity in a location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','pndqvl','Pending Capacity','F','8','0','0','0','Much the same as the other "qvl" numbers, this field is used to indicate how much capacity is pending storage to the location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','trfpct','Top-Off Replenishment Percent','I','4','1','0','0','Indicates what percentage of the maxqvl should be used when performing top-off replenishments.  A value of 0 will indicate 100%.  50 will indicate half full.  This can be useful if it is desired to "overfill" a loc during repl process','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','erfpct','Emergency Replenishment Percent','I','4','1','0','0','Much the same as trfpct, this field indicates the percentage of maxqvl which should be used during emergency replenishment operations.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','esc_type','Escalation Type','S','40','1','0','0','Escalation Type - Location capacity escalation type.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','esc_thr','Escalation Threshold','F','8','1','0','0','Escalation Threshold - Escalation Threshold','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','useflg','Location Usable','I','4','1','0','0','This flag indicates that the location is usable.  If set to false, future allocations and stores are disabled at this location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','stoflg','Storable','I','4','1','0','0','This flag indicates that the location is available for storage operations.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','pckflg','Pickable','I','4','1','0','0','This flag indicates that the location is available for picking (allocation) operations.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','repflg','Replenishment','I','4','1','0','0','This flag indicates that the location may be replenished.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','asgflg','Assignment','I','4','1','0','0','This flag indicates that this loc is permanently assigned. In processing area, it applies to rescod value that is set. In normal sto. areas, it indicates itmnum is assigned to loc. STORE-ASG-LOC policies tells the item that is assigned','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','cipflg','Count In Progress','I','4','1','0','0','This flag indicates that there is a count in-progress at this location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','cntseq','Count Sequence','S','20','1','0','0','Much like travel sequence, this field is used to sequence counting activities.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','numcnt','Number of Counts','I','4','0','0','0','Operational column used to track the number of counts performed during a particular cycle.  Used when location based cycle counting is in effect.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','abccod','ABC Code','S','1','1','0','0','Used to schedule location based cycle counts much in the same was as the itmmst.abccod is used.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','cntdte','Count Date','D','14','1','0','0','Date location was last counted.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','devcod','Device Code','S','20','1','0','0','Label device which is closest to this location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','lokcod','Location Lock Code','S','20','1','0','0','Used to indicate that this loc is locked for processing.  Often used by operational programs such as order overpack operations to indicate that a work station is processing a particular lane - this prevents collisions during processing.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','locacc','Location Access','S','30','1','0','0','Used to indicate that special vehicle access is necessary to get to this location.  This is used by the work manangement system to ensure that work is only sent to devices if the device can access the location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','voc_chkdgt','Voice Check Digit','S','5','1','0','0','Voice Check Digit - This will be a short code that will be used in voice to identify a location.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','voc_chkdgt_2','Voice Check Digit 2','S','5','1','0','0','Voice Check Digit 2 - This will be a short code that will be used in voice to identify a location in addition to the standard Check Digit, used when the check digit rotation policy is configured.','Warehouse Layout');
insert into WMS_DB_SCHEMA values ('locmst','voc_chkdgt_3','Voice Check Digit 3','S','5','1','0','0','Voice Check Digit 3 - This will be a short code that will be used in voice to identify a location in addition to the standard Check Digit, used when the check digit rotation policy is configured.','Warehouse Layout');
